// Config — replace with your values
const SUPABASE_URL = 'https://ainspdnploxzrujbgcqo.supabase.co';
const SUPABASE_KEY = 'PEGA_TU_SUPABASE_SERVICE_KEY_AQUI';
const APIFY_TOKEN = 'PEGA_TU_APIFY_TOKEN_AQUI';
const ANTHROPIC_KEY = 'PEGA_TU_ANTHROPIC_API_KEY_AQUI';

const competitors = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/competitor_profiles?or=(ig_status.eq.found,tiktok_status.eq.found)&order=last_scraped_at.asc.nullsfirst&limit=15`,
  headers: {
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'apikey': SUPABASE_KEY
  },
  json: true
});

console.log(`Found ${competitors.length} competitors with IG/TikTok profiles`);
if (competitors.length === 0) return [];

const tasks = [];
for (const c of competitors) {
  if (c.ig_status === 'found' && c.ig_handle) {
    tasks.push({
      json: {
        competitor_id: c.id,
        competitor_name: c.fb_page_name,
        platform: 'instagram',
        handle: c.ig_handle,
        profile_url: c.ig_profile_url,
        _supabase_url: SUPABASE_URL,
        _supabase_key: SUPABASE_KEY,
        _apify_token: APIFY_TOKEN,
        _anthropic_key: ANTHROPIC_KEY
      }
    });
  }
  if (c.tiktok_status === 'found' && c.tiktok_handle) {
    tasks.push({
      json: {
        competitor_id: c.id,
        competitor_name: c.fb_page_name,
        platform: 'tiktok',
        handle: c.tiktok_handle,
        profile_url: c.tiktok_profile_url,
        _supabase_url: SUPABASE_URL,
        _supabase_key: SUPABASE_KEY,
        _apify_token: APIFY_TOKEN,
        _anthropic_key: ANTHROPIC_KEY
      }
    });
  }
}

console.log(`Created ${tasks.length} scrape tasks`);
return tasks;

const task = $input.first().json;

let runId = null;
try {
  const runs = await this.helpers.httpRequest({
    method: 'POST',
    url: `${task._supabase_url}/rest/v1/scrape_runs`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: {
      source: task.platform,
      keyword: task.handle,
      competitor_id: task.competitor_id,
      status: 'running',
      max_results: 30
    },
    json: true
  });
  runId = runs[0]?.id || null;
} catch(e) {
  console.log('Create run error:', e.message);
}

return [{ json: { ...task, _run_id: runId } }];

const task = $input.first().json;
console.log(`Scraping IG posts for @${task.handle}`);

const MIN_VIEWS = 50000;
const MIN_LIKES_IMAGE = 5000;

try {
  const rawPosts = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~instagram-scraper/run-sync-get-dataset-items?token=${task._apify_token}&timeout=180`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      directUrls: [`https://instagram.com/${task.handle}`],
      resultsType: 'posts',
      resultsLimit: 30,
      addParentData: true
    },
    json: true,
    timeout: 200000
  });

  console.log(`IG raw posts: ${rawPosts.length}`);

  const posts = [];
  for (const p of rawPosts) {
    const isVideo = p.type === 'Video' || p.videoUrl;
    const views = p.videoViewCount || p.videoPlayCount || 0;
    const likes = p.likesCount || 0;

    if (isVideo && views < MIN_VIEWS) continue;
    if (!isVideo && likes < MIN_LIKES_IMAGE) continue;

    posts.push({
      competitor_id: task.competitor_id,
      platform: 'instagram',
      post_type: isVideo ? 'video' : (p.type === 'Sidecar' ? 'carousel' : 'image'),
      post_url: p.url || p.inputUrl || null,
      post_id: p.id || p.shortCode || null,
      posted_at: p.timestamp || null,
      views: views,
      likes: likes,
      comments: p.commentsCount || 0,
      shares: 0,
      caption: (p.caption || '').substring(0, 5000),
      media_url: p.videoUrl || p.displayUrl || null,
      thumbnail_url: p.displayUrl || null
    });
  }

  console.log(`IG filtered posts: ${posts.length} (from ${rawPosts.length})`);
  return [{ json: { ...task, _posts: posts, _total_scraped: rawPosts.length } }];

} catch(e) {
  console.log('IG scraping error:', e.message);
  return [{ json: { ...task, _posts: [], _error: e.message, _total_scraped: 0 } }];
}

const task = $input.first().json;
console.log(`Scraping TikTok posts for @${task.handle}`);

const MIN_VIEWS = 50000;

try {
  const rawPosts = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~tiktok-scraper/run-sync-get-dataset-items?token=${task._apify_token}&timeout=180`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      profiles: [task.handle],
      resultsPerPage: 30,
      shouldDownloadVideos: false
    },
    json: true,
    timeout: 200000
  });

  console.log(`TikTok raw posts: ${rawPosts.length}`);

  const posts = [];
  for (const p of rawPosts) {
    const views = p.playCount || p.stats?.playCount || 0;
    const likes = p.diggCount || p.stats?.diggCount || 0;

    if (views < MIN_VIEWS) continue;

    posts.push({
      competitor_id: task.competitor_id,
      platform: 'tiktok',
      post_type: 'video',
      post_url: p.webVideoUrl || `https://tiktok.com/@${task.handle}/video/${p.id}`,
      post_id: p.id || null,
      posted_at: p.createTimeISO || (p.createTime ? new Date(p.createTime * 1000).toISOString() : null),
      views: views,
      likes: likes,
      comments: p.commentCount || p.stats?.commentCount || 0,
      shares: p.shareCount || p.stats?.shareCount || 0,
      caption: (p.text || p.desc || '').substring(0, 5000),
      media_url: p.videoUrl || null,
      thumbnail_url: p.covers?.default || p.video?.cover || null
    });
  }

  console.log(`TikTok filtered posts: ${posts.length} (from ${rawPosts.length})`);
  return [{ json: { ...task, _posts: posts, _total_scraped: rawPosts.length } }];

} catch(e) {
  console.log('TikTok scraping error:', e.message);
  return [{ json: { ...task, _posts: [], _error: e.message, _total_scraped: 0 } }];
}

const task = $input.first().json;
const posts = task._posts || [];

console.log(`Saving ${posts.length} posts for ${task.competitor_name} (${task.platform})`);

let savedCount = 0;
let errorCount = 0;

for (const post of posts) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${task._supabase_url}/rest/v1/organic_posts?on_conflict=platform,post_id`,
      headers: {
        'Authorization': `Bearer ${task._supabase_key}`,
        'apikey': task._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates,return=minimal'
      },
      body: post,
      json: true
    });
    savedCount++;
  } catch(e) {
    console.log(`Save error for post ${post.post_id}: ${e.message}`);
    errorCount++;
  }
}

console.log(`Saved: ${savedCount}, Errors: ${errorCount}`);

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${task._supabase_url}/rest/v1/competitor_profiles?id=eq.${task.competitor_id}`,
    headers: {
      'Authorization': `Bearer ${task._supabase_key}`,
      'apikey': task._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: { last_scraped_at: new Date().toISOString() },
    json: true
  });
} catch(e) {
  console.log('Update last_scraped_at failed:', e.message);
}

return [{
  json: {
    ...task,
    _saved: savedCount,
    _errors: errorCount,
    _post_ids: posts.filter(p => p.post_id).map(p => p.post_id)
  }
}];

const task = $input.first().json;
const postIds = task._post_ids || [];

if (postIds.length === 0) {
  console.log('No posts to analyze');
  return [{ json: { ...task, _analyzed: 0 } }];
}

const posts = await this.helpers.httpRequest({
  method: 'GET',
  url: `${task._supabase_url}/rest/v1/organic_posts?competitor_id=eq.${task.competitor_id}&platform=eq.${task.platform}&analyzed_at=is.null&limit=10`,
  headers: {
    'Authorization': `Bearer ${task._supabase_key}`,
    'apikey': task._supabase_key
  },
  json: true
});

console.log(`Analyzing ${posts.length} posts for ${task.competitor_name}`);

let analyzed = 0;

for (const post of posts) {
  try {
    const captionPreview = (post.caption || 'No caption').replace(/[\"\n\r]/g, ' ').substring(0, 2000);

    // Step 1: Content analysis with Sonnet
    let analysis = null;
    try {
      const analysisResult = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.anthropic.com/v1/messages',
        headers: {
          'x-api-key': task._anthropic_key,
          'anthropic-version': '2023-06-01',
          'Content-Type': 'application/json'
        },
        body: {
          model: 'claude-sonnet-4-5-20250929',
          max_tokens: 800,
          system: 'You are an expert content analyst. Analyze organic social media posts for strategic intelligence. Respond in Spanish.',
          messages: [{
            role: 'user',
            content: `Analyze this ${post.platform} post:\n\nCaption: ${captionPreview}\nType: ${post.post_type}\nViews: ${post.views}\nLikes: ${post.likes}\nComments: ${post.comments}\n\nProvide a 2-3 sentence strategic analysis: what content type, hook technique, audience targeting, and why it likely went viral.`
          }]
        },
        json: true,
        timeout: 60000
      });
      analysis = analysisResult.content?.[0]?.text || null;
    } catch(e) {
      console.log('Analysis error:', e.message);
    }

    // Step 2: Rewrite with Opus (only if has caption)
    let rewritten = null;
    if (post.caption && post.caption.length > 20) {
      try {
        const rewriteResult = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://api.anthropic.com/v1/messages',
          headers: {
            'x-api-key': task._anthropic_key,
            'anthropic-version': '2023-06-01',
            'Content-Type': 'application/json'
          },
          body: {
            model: 'claude-opus-4-6',
            max_tokens: 1500,
            system: 'You are a world-class direct-response copywriter. Rewrite social media captions maintaining the same persuasion structure but with fresh wording. Write in the same language as the original.',
            messages: [{
              role: 'user',
              content: `Rewrite this ${post.platform} caption maintaining the same hook, structure, and CTA style. Make it sound human, not AI:\n\n${captionPreview}\n\nJust output the rewritten caption, nothing else.`
            }]
          },
          json: true,
          timeout: 90000
        });
        rewritten = rewriteResult.content?.[0]?.text || null;
      } catch(e) {
        console.log('Rewrite error:', e.message);
      }
    }

    // Save analysis back to post
    try {
      await this.helpers.httpRequest({
        method: 'PATCH',
        url: `${task._supabase_url}/rest/v1/organic_posts?id=eq.${post.id}`,
        headers: {
          'Authorization': `Bearer ${task._supabase_key}`,
          'apikey': task._supabase_key,
          'Content-Type': 'application/json',
          'Prefer': 'return=minimal'
        },
        body: {
          content_analysis: analysis,
          rewritten_copy: rewritten,
          analyzed_at: new Date().toISOString()
        },
        json: true
      });
      analyzed++;
    } catch(e) {
      console.log('Update failed:', e.message);
    }

  } catch(e) {
    console.log(`Analysis error for post ${post.id}:`, e.message);
  }
}

console.log(`Analyzed ${analyzed} of ${posts.length} posts`);
return [{ json: { ...task, _analyzed: analyzed } }];

const task = $input.first().json;
const now = new Date().toISOString();

if (task._run_id) {
  const status = task._error ? 'failed' : (task._errors > 0 ? 'partial' : 'completed');

  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${task._supabase_url}/rest/v1/scrape_runs?id=eq.${task._run_id}`,
      headers: {
        'Authorization': `Bearer ${task._supabase_key}`,
        'apikey': task._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        status: status,
        completed_at: now,
        total_scraped: task._total_scraped || 0,
        total_filtered: task._saved || 0,
        total_analyzed: task._analyzed || 0,
        total_errors: task._errors || 0,
        error_message: task._error || null
      },
      json: true
    });
  } catch(e) {
    console.log('Run update failed:', e.message);
  }
}

console.log(`Done: ${task.competitor_name} (${task.platform}) — scraped: ${task._total_scraped}, saved: ${task._saved}, analyzed: ${task._analyzed}`);
return [{ json: { done: true, competitor: task.competitor_name, platform: task.platform } }];
